function sceneStemFor(bookNumber, chapterId) {
  const book = String(bookNumber).padStart(2, '0');
  const chapter = String(chapterId);
  return `chapter-b${book}-${chapter === 'praef' ? 'praef' : `c${chapter.padStart(3, '0')}`}`;
}

export function chapterSceneSourceFor(bookNumber, chapterId) {
  const hash = CHAPTER_SCENE_DELIVERY_HASHES[`${bookNumber}:${chapterId}`];
  if (!hash) return null;
  const stem = sceneStemFor(bookNumber, chapterId);
  const base = `/assets/${stem}.${hash}`;
  const mobileAvif = `${base}.w1024.avif`;
  const mobileWebp = `${base}.w1024.webp`;
  const mobileJpeg = `${base}.w1024.jpg`;
  const nativeAvif = `${base}.w1536.avif`;
  return {
    logicalPath: `/chapter-scenes/${stem}.png`,
    desktop: {
      fallback: mobileJpeg,
      preload: nativeAvif,
      imageSet: `image-set(url("${nativeAvif}") type("image/avif") 1x, url("${mobileWebp}") type("image/webp") 1x)`,
    },
    mobile: {
      fallback: mobileJpeg,
      preload: mobileAvif,
      imageSet: `image-set(url("${mobileAvif}") type("image/avif") 1x, url("${nativeAvif}") type("image/avif") 2x, url("${mobileWebp}") type("image/webp") 1x)`,
    },
    derivatives: [mobileAvif, mobileWebp, mobileJpeg, nativeAvif],
  };
}
